// Hero demo on the home page. Generated by _build/build.py from template.html; do not edit by hand.
(function () {
  var demo = document.getElementById('demo');
  if (!demo) return;
  var rows = Array.prototype.slice.call(demo.querySelectorAll('.boq-row'));
  var state = document.getElementById('boq-state');
  var approve = document.getElementById('approve');

  function current() { return demo.querySelector('.boq-row[aria-pressed="true"]'); }

  function refresh() {
    var done = demo.querySelectorAll('.boq-row.is-approved').length;
    state.textContent = (done === rows.length ? demo.dataset.tAll : demo.dataset.tProgress).replace('{done}', done).replace('{total}', rows.length);
    state.classList.toggle('done', done === rows.length);
    var cur = current();
    approve.textContent = cur && cur.classList.contains('is-approved') ? demo.dataset.tApproved : demo.dataset.tApprove;
    approve.disabled = !!(cur && cur.classList.contains('is-approved'));
    approve.style.opacity = approve.disabled ? '.55' : '';
    approve.style.cursor = approve.disabled ? 'default' : '';
  }

  function select(key) {
    rows.forEach(function (r) { r.setAttribute('aria-pressed', r.dataset.key === key ? 'true' : 'false'); });
    demo.setAttribute('data-sel', key);
    refresh();
  }

  rows.forEach(function (r) {
    r.addEventListener('click', function () { select(r.dataset.key); });
  });
  Array.prototype.forEach.call(demo.querySelectorAll('.plan .el'), function (g) {
    g.addEventListener('click', function () { select(g.dataset.key); });
  });
  approve.addEventListener('click', function () {
    var cur = current();
    if (!cur) return;
    cur.classList.add('is-approved');
    var next = rows.filter(function (r) { return !r.classList.contains('is-approved'); })[0];
    if (next) select(next.dataset.key); else refresh();
  });
  refresh();
})();
